// Kotlin factories need the Kotlin runtime, so Java callers never load them.
_OwnedConvert.Factory kotlinFactory() {
    var factory = kotlinFactory;
    if (factory == null) synchronized (this) {
        factory = kotlinFactory;
        if (factory == null) kotlinFactory = factory = new _KotlinOwnedFactories(this);
    }
    return factory;

// Java consumers carry no Kotlin runtime, so only the lazy accessor may
// construct the Kotlin factories.
const bindings = Object.entries(generated.jvm.files).find(([path]) =>
	path.endsWith("/_OwnedBindings.java"))[1];
assert.equal(bindings.split("new _KotlinOwnedFactories(").length, 2);
